struct Dompet { saldo: int }

impl Dompet {
    fn baru(awal: int) -> Dompet { return Dompet { saldo: awal } }
    fn lihat(self) -> int { return self.saldo }
    fn tarik(self, n: int) -> Dompet {
        if n > self.saldo { return self }      // aturannya di sini saja
        return Dompet { saldo: self.saldo - n }
    }
}

pub fn main() {
    var d = Dompet::baru(50000)
    d = d.tarik(20000)
    d = d.tarik(999999)      // ditolak diam-diam oleh aturannya
    wok("Saldo:", d.lihat())
}

