struct Titik {
    x: float,
    y: float
}

impl Titik {
    fn baru(x: float, y: float) -> Titik {
        return Titik { x: x, y: y }
    }
    fn asal() -> Titik {
        return Titik { x: 0.0, y: 0.0 }
    }
    fn jarakKe(self, lain: Titik) -> float {
        let dx = self.x - lain.x
        let dy = self.y - lain.y
        return math::sqrt(dx * dx + dy * dy)
    }
}

pub fn main() {
    let p = Titik::baru(3.0, 4.0)
    wok("Jarak ke titik asal:", p.jarakKe(Titik::asal()))
}

