pub fn main() {
    wok("Barisan aritmatika (a=2, b=3):")
    let a = 2
    let b = 3

    for _, n in 1..=6 {
        let suku = a + (n - 1) * b
        wok_(suku, " ")
    }
    wok("")

    // Deret: total 6 suku pertama
    let mut total = 0
    for _, n in 1..=6 {
        total += a + (n - 1) * b
    }
    wok("Jumlah 6 suku pertama:", total)
}

fn keRadian(derajat: float) -> float {
    return derajat * (math::PI / 180.0)
}

pub fn main() {
    let sudut = keRadian(60.0)
    let jarak = 20.0

    let tinggi = jarak * math::tan(sudut)
    wok("Tinggi tiang:", tinggi, "meter")
}

fn hitungMean(data: []float) -> float {
    let mut total = 0.0
    for _, n in data { total += n }
    return total / data.len() as float
}

fn tentukanGrade(rata: float) -> string {
    if rata >= 90.0 { return "A - Luar Biasa" }
    else if rata >= 80.0 { return "B - Bagus" }
    else if rata >= 70.0 { return "C - Cukup" }
    else if rata >= 60.0 { return "D - Perlu Perbaikan" }
    else { return "E - Belum Lulus" }
}

pub fn main() {
    let nilai = [78.0, 85.0, 92.0, 67.0, 88.0]
    let rata = hitungMean(nilai)

    wok("Rata-rata:", rata)
    wok("Median:", arr::median(nilai))
    wok("Grade:", tentukanGrade(rata))
}
